"""Política de decisão pura — recebe estado e resultado, devolve decisão. Sem relógio, sem rede,
sem LLM."""
from __future__ import annotations

from dominio.decisao import Decisao, MotivoHandoff, TipoDecisao
from dominio.estado_conversa import EstadoDaConversa
from dominio.resultado_cotacao import ResultadoDaCotacao, StatusCotacao


def decidir(estado: EstadoDaConversa, resultado: ResultadoDaCotacao | None) -> Decisao:
    if estado.campos_faltantes:
        return Decisao(TipoDecisao.COLETAR_INFORMACAO)
    if resultado is None:
        return Decisao(TipoDecisao.COTAR)
    # R5 (issue #16): erro_de_payload e timeout viram ENCAMINHAR, diferenciados só pelo motivo —
    # nenhum dos dois é culpa do lead, e nos dois um humano precisa saber que não deu para cotar.
    match resultado.status:
        case StatusCotacao.SUCESSO:
            return Decisao(TipoDecisao.EXPLICAR_COTACAO)
        case StatusCotacao.RECUSA_DE_NEGOCIO:
            return Decisao(TipoDecisao.ENCERRAR)
        case StatusCotacao.INDISPONIVEL:
            return Decisao(TipoDecisao.ENCAMINHAR, reason_code=MotivoHandoff.QUOTE_INDISPONIVEL)
        case StatusCotacao.TIMEOUT:
            return Decisao(TipoDecisao.ENCAMINHAR, reason_code=MotivoHandoff.QUOTE_TIMEOUT)
        case StatusCotacao.ERRO_DE_PAYLOAD:
            return Decisao(TipoDecisao.ENCAMINHAR, reason_code=MotivoHandoff.QUOTE_ERRO_DE_PAYLOAD)
        case _:
            raise AssertionError(f"StatusCotacao sem decisao mapeada: {resultado.status!r}")

"""Resultado de uma tentativa de cotação — estados explícitos, sem IO."""
from __future__ import annotations

from dataclasses import dataclass
from enum import Enum

from dominio.preco_cotado import PrecoCotado


class StatusCotacao(str, Enum):
    SUCESSO = "sucesso"
    RECUSA_DE_NEGOCIO = "recusa_de_negocio"
    ERRO_DE_PAYLOAD = "erro_de_payload"
    INDISPONIVEL = "indisponivel"
    TIMEOUT = "timeout"


@dataclass(frozen=True)
class ResultadoDaCotacao:
    status: StatusCotacao
    preco: PrecoCotado | None = None
    motivo: str | None = None

    def __post_init__(self) -> None:
        if self.status == StatusCotacao.SUCESSO:
            if self.preco is None:
                raise ValueError("status sucesso exige preco (nenhuma cotação bem-sucedida sem PrecoCotado)")
            if self.motivo is not None:
                raise ValueError("status sucesso não aceita motivo — preco e motivo são mutuamente exclusivos")
        else:
            if self.preco is not None:
                raise ValueError(f"status {self.status.value} não aceita preco — preco e motivo são mutuamente exclusivos")
            if self.motivo is None:
                raise ValueError(f"status {self.status.value} exige motivo")

    @classmethod
    def sucesso(cls, preco: PrecoCotado) -> "ResultadoDaCotacao":
        return cls(status=StatusCotacao.SUCESSO, preco=preco)

    @classmethod
    def recusa_de_negocio(cls, motivo: str) -> "ResultadoDaCotacao":
        return cls(status=StatusCotacao.RECUSA_DE_NEGOCIO, motivo=motivo)

    @classmethod
    def erro_de_payload(cls, motivo: str) -> "ResultadoDaCotacao":
        return cls(status=StatusCotacao.ERRO_DE_PAYLOAD, motivo=motivo)

    @classmethod
    def indisponivel(cls, motivo: str) -> "ResultadoDaCotacao":
        return cls(status=StatusCotacao.INDISPONIVEL, motivo=motivo)

    @classmethod
    def timeout(cls, motivo: str) -> "ResultadoDaCotacao":
        return cls(status=StatusCotacao.TIMEOUT, motivo=motivo)

